<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Activity, ChevronLeft, CircleCheck, LoaderCircle, Pencil, Plus, Play, RefreshCw, Search, Settings2, ShieldCheck, Trash2, X } from 'lucide-vue-next'
import { CONFIRM_PHRASE, cancelClear, clearMemory, confirmMatches, requestClear, settings } from './settings'

const WS_URL = import.meta.env.VITE_WS_URL ?? 'ws://localhost:8000/ws'
const REST_BASE = new URL(WS_URL.replace(/^ws/, 'http')).origin
type View = 'hub' | 'models' | 'memory'
interface ModelOption { id: string; name: string; source?: string }
interface Provider { id: string; name: string; base_url: string; needs_key: boolean; models: ModelOption[] }
interface Profile { id: string; provider_id: string; model_id: string; display_name: string; api_key_set: boolean; verified: boolean; active: boolean }

const view = ref<View>('hub'); const providers = ref<Provider[]>([]); const profiles = ref<Profile[]>([]); const activeId = ref<string | null>(null)
const DEFAULT_PROVIDER = 'deepseek'; const DEFAULT_MODEL = 'deepseek-v4-flash'
const dialogOpen = ref(false); const dialogProfile = ref<Profile | null>(null); const dialogProvider = ref(DEFAULT_PROVIDER); const dialogModel = ref(''); const dialogKey = ref(''); const modelSearch = ref(''); const loading = ref(false); const discovering = ref(false); const message = ref(''); const deleteTarget = ref<Profile | null>(null)
const visible = computed(() => settings.open); const activeProfile = computed(() => profiles.value.find((p) => p.id === activeId.value)); const selectedProvider = computed(() => providers.value.find((p) => p.id === dialogProvider.value)); const filteredModels = computed(() => (selectedProvider.value?.models ?? []).filter((m) => `${m.name} ${m.id}`.toLowerCase().includes(modelSearch.value.trim().toLowerCase())))
function modelOptionLabel(model: ModelOption): string {
  const normalize = (value: string): string => value.toLowerCase().replace(/[^a-z0-9]/g, '')
  return normalize(model.name) === normalize(model.id) ? model.name : `${model.name} · ${model.id}`
}
watch(filteredModels, (models) => { if (dialogOpen.value && !models.some((model) => model.id === dialogModel.value)) dialogModel.value = models[0]?.id ?? '' })

async function json<T>(path: string, init?: RequestInit): Promise<T> { const response = await fetch(`${REST_BASE}${path}`, init); if (!response.ok) throw new Error(((await response.json().catch(() => null)) as { detail?: string } | null)?.detail ?? '请求失败'); return await response.json() as T }
async function loadModels(): Promise<void> { try { const [catalog, saved] = await Promise.all([json<{ providers: Provider[] }>('/admin/llm/catalog'), json<{ active_id: string | null; profiles: Profile[] }>('/admin/llm/profiles')]); providers.value = catalog.providers.sort((a, b) => a.id === DEFAULT_PROVIDER ? -1 : b.id === DEFAULT_PROVIDER ? 1 : 0); profiles.value = saved.profiles; activeId.value = saved.active_id } catch (err) { message.value = err instanceof Error ? err.message : '模型服务暂时不可用。' } }
function go(next: View): void { view.value = next; if (next === 'models') void loadModels() }
function close(): void { settings.open = false; view.value = 'hub'; dialogOpen.value = false }
function openDialog(profile: Profile | null = null): void { dialogProfile.value = profile; dialogProvider.value = profile?.provider_id ?? DEFAULT_PROVIDER; const models = providers.value.find((p) => p.id === (profile?.provider_id ?? DEFAULT_PROVIDER))?.models ?? []; dialogModel.value = profile?.model_id ?? (models.some((m) => m.id === DEFAULT_MODEL) ? DEFAULT_MODEL : models[0]?.id ?? DEFAULT_MODEL); dialogKey.value = ''; modelSearch.value = ''; message.value = ''; dialogOpen.value = true }
function selectProvider(id: string): void { dialogProvider.value = id; const models = providers.value.find((p) => p.id === id)?.models ?? []; dialogModel.value = models[0]?.id ?? '' }
async function discoverModels(): Promise<void> { if (discovering.value || !dialogProvider.value) return; discovering.value = true; try { const result = await json<{ provider_id: string; models: ModelOption[]; live_error: string | null }>('/admin/llm/models', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ provider_id: dialogProvider.value, ...(dialogKey.value ? { api_key: dialogKey.value } : {}) }) }); const provider = providers.value.find((item) => item.id === result.provider_id); if (provider) provider.models = result.models; if (!result.models.some((item) => item.id === dialogModel.value)) dialogModel.value = result.models[0]?.id ?? ''; message.value = result.live_error ?? `已更新 ${result.models.length} 个模型候选。` } catch (err) { message.value = err instanceof Error ? err.message : '模型搜索暂时不可用。' } finally { discovering.value = false } }
async function saveModel(): Promise<void> { if (!dialogModel.value || loading.value) return; loading.value = true; try { const body = { provider_id: dialogProvider.value, model_id: dialogModel.value, ...(dialogKey.value ? { api_key: dialogKey.value } : {}) }; if (dialogProfile.value) await json(`/admin/llm/profiles/${dialogProfile.value.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model_id: dialogModel.value, ...(dialogKey.value ? { api_key: dialogKey.value } : {}) }) }); else await json('/admin/llm/profiles', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); dialogOpen.value = false; message.value = '模型已保存并完成激活验证。'; await loadModels() } catch (err) { message.value = err instanceof Error ? err.message : '模型保存失败。' } finally { loading.value = false } }
async function activate(profile: Profile): Promise<void> { if (loading.value || profile.active) return; loading.value = true; try { await json(`/admin/llm/profiles/${profile.id}/activate`, { method: 'POST' }); await loadModels() } catch (err) { message.value = err instanceof Error ? err.message : '模型启动失败。' } finally { loading.value = false } }
async function remove(): Promise<void> { if (!deleteTarget.value) return; try { await json(`/admin/llm/profiles/${deleteTarget.value.id}`, { method: 'DELETE' }); deleteTarget.value = null; await loadModels() } catch (err) { message.value = err instanceof Error ? err.message : '模型删除失败。' } }
function displayProvider(id: string): string { return providers.value.find((p) => p.id === id)?.name ?? id }
function providerIcon(id: string): string { return `/provider-icons/${id}.svg` }
function fallbackIcon(event: Event): void {
  const image = event.target as HTMLImageElement
  image.style.display = 'none'
  const fallback = image.nextElementSibling as HTMLElement | null
  if (fallback !== null) fallback.style.display = 'block'
}
watch(() => settings.open, (open) => { if (open) void loadModels() })
</script>

<template>
  <aside class="settings-panel" :class="{ open: visible }" aria-label="设置">
    <header class="settings-head"><button v-if="view !== 'hub'" class="icon-button" type="button" title="返回设置" aria-label="返回设置" @click="view = 'hub'"><ChevronLeft :size="17" /></button><div><h2>设置</h2><p v-if="view === 'hub'">照顾好陪伴，也照顾好记忆。</p><p v-else-if="view === 'models'">选择此刻要陪你说话的模型。</p><p v-else>看看留下了什么，也决定留下什么。</p></div><button class="icon-button" type="button" title="关闭设置" aria-label="关闭设置" @click="close"><X :size="17" /></button></header>
    <div v-if="message" class="settings-message"><CircleCheck :size="14" />{{ message }}</div>
    <div v-if="view === 'hub'" class="settings-hub"><button class="settings-card" type="button" @click="go('models')"><span class="card-icon model"><Settings2 :size="19" /></span><span><b>模型服务</b><small>{{ activeProfile?.display_name ?? '默认：DeepSeek · deepseek-v4-flash' }}</small></span><ChevronLeft class="right-arrow" :size="17" /></button><button class="settings-card" type="button" @click="go('memory')"><span class="card-icon memory"><ShieldCheck :size="19" /></span><span><b>记忆治理</b><small>情绪趋势与记忆清除</small></span><ChevronLeft class="right-arrow" :size="17" /></button></div>
    <div v-else-if="view === 'models'" class="settings-body"><div class="model-toolbar"><span class="section-label">已保存的模型</span><button class="round-add" type="button" title="添加模型厂商" aria-label="添加模型厂商" @click="openDialog()"><Plus :size="16" /></button></div><article v-if="profiles.length === 0" class="model-card"><div class="provider-icon"><img :src="providerIcon(DEFAULT_PROVIDER)" alt="DeepSeek" @error="fallbackIcon"><span>深</span></div><div class="model-copy"><b>DeepSeek</b><small>{{ DEFAULT_MODEL }}</small><span><i></i>待配置 API Key</span></div><div class="model-actions"><button class="icon-action" type="button" disabled title="配置后可启动" aria-label="配置后可启动"><Play :size="16" /></button><button class="icon-action" type="button" title="配置默认模型" aria-label="配置默认模型" @click="openDialog()"><Pencil :size="16" /></button></div></article><article v-for="profile in profiles" :key="profile.id" class="model-card" :class="{ active: profile.active }"><div class="provider-icon"><img :src="providerIcon(profile.provider_id)" :alt="displayProvider(profile.provider_id)" @error="fallbackIcon"><span>{{ displayProvider(profile.provider_id).slice(0, 1) }}</span></div><div class="model-copy"><b>{{ displayProvider(profile.provider_id) }}</b><small>{{ profile.model_id }}</small><span><i :class="{ on: profile.active }"></i>{{ profile.active ? '运行中' : profile.verified ? '已验证' : '待启动' }}</span></div><div class="model-actions"><button class="icon-action" type="button" :disabled="profile.active || loading" :title="profile.active ? '运行中' : '启动模型'" :aria-label="profile.active ? '运行中' : '启动模型'" @click="activate(profile)"><LoaderCircle v-if="loading && !profile.active" class="spin" :size="16" /><Play v-else :size="16" /></button><button class="icon-action" type="button" title="设置模型" aria-label="设置模型" @click="openDialog(profile)"><Pencil :size="16" /></button><button class="icon-action danger" type="button" :disabled="profile.active" title="删除模型" aria-label="删除模型" @click="deleteTarget = profile"><Trash2 :size="16" /></button></div></article><p class="settings-tip"><Activity :size="14" />启动前会由 LiteLLM 做最小连接验证，API Key 只显示配置状态。</p></div>
    <div v-else class="settings-body memory-view"><div class="section-label">情绪趋势</div><div class="trends"><p v-if="settings.trends.length === 0" class="settings-empty">暂无情绪记录。</p><div v-for="(trend, index) in settings.trends" :key="`${trend.date}-${index}`" class="trend-row"><span>{{ trend.date }}</span><b>{{ trend.mood_label }}</b><small>{{ trend.source }}</small></div></div><div class="memory-danger"><p>清除后不可恢复。</p><button type="button" @click="requestClear"><Trash2 :size="14" />一键清除记忆</button></div></div>
    <div v-if="dialogOpen" class="model-dialog"><div class="dialog-card"><header><div><h3>{{ dialogProfile ? '设置模型' : '添加模型厂商' }}</h3><p>厂商和模型来自后端目录，API Key 只在本机加密保存。</p></div><button class="icon-button" type="button" title="关闭" aria-label="关闭" @click="dialogOpen = false"><X :size="16" /></button></header><label>模型厂商<div class="provider-select"><button v-for="provider in providers" :key="provider.id" type="button" :class="{ selected: dialogProvider === provider.id }" @click="selectProvider(provider.id)">{{ provider.name }}</button></div></label><label>API Key<input v-model="dialogKey" type="password" :placeholder="dialogProfile?.api_key_set ? '已配置 · 留空保持不变' : selectedProvider?.needs_key ? '请输入 API Key 后可搜索实时模型' : '本地服务无需 API Key'" /></label><label>模型名称<div class="search-row"><div class="search-input"><Search :size="15" /><input v-model="modelSearch" placeholder="按名称或 ID 搜索" /><span>{{ filteredModels.length }}</span></div><button class="icon-action refresh-action" type="button" :disabled="discovering" title="从服务商获取最新模型" aria-label="从服务商获取最新模型" @click="discoverModels"><LoaderCircle v-if="discovering" class="spin" :size="15" /><RefreshCw v-else :size="15" /></button></div><select v-model="dialogModel"><option v-for="model in filteredModels" :key="model.id" :value="model.id">{{ modelOptionLabel(model) }}{{ model.source === 'live' ? ' · 实时' : '' }}</option></select></label><div class="dialog-actions"><button class="secondary-action" type="button" @click="dialogOpen = false">取消</button><button class="primary-action" type="button" :disabled="loading || !dialogModel" @click="saveModel"><LoaderCircle v-if="loading" class="spin" />保存并验证</button></div></div></div>
    <div v-if="deleteTarget" class="model-dialog"><div class="confirm-card"><h3>要把这个模型请出列表吗？</h3><p>{{ deleteTarget.display_name }} 的本地配置会被移除，正在运行的模型不能删除。</p><div class="dialog-actions"><button class="secondary-action" type="button" @click="deleteTarget = null">先留着</button><button class="danger-action" type="button" @click="remove"><Trash2 :size="14" />确认删除</button></div></div></div>
    <div v-if="settings.confirmOpen" class="memory-confirm"><h3>确认清除全部记忆？</h3><p>当前会话、摘要、心情趋势和方案书都会被清除。</p><code>{{ CONFIRM_PHRASE }}</code><input v-model="settings.confirmInput" :placeholder="CONFIRM_PHRASE" /><div class="dialog-actions"><button class="secondary-action" type="button" @click="cancelClear">取消</button><button class="danger-action" type="button" :disabled="!confirmMatches(settings.confirmInput)" @click="clearMemory">确认清除</button></div></div>
  </aside>
</template>

<style scoped>
